README.txt
- Purpose: Deploy AWS KMS CMK, PrivateLink endpoints (prod/nonprod), Snowflake PrivateLink and network policy scaffolding, and optional Okta/SIEM integrations.
- Region: us-west-2 (override in vars).
- Replace all placeholders beginning with TBD_ before production cutover, or proceed to lab with defaults.

vars.auto.tfvars.example
aws_account_id         = "TBD_AWS_ACCOUNT_ID"
aws_region             = "us-west-2"
tags = {
  Owner       = "TBD_TAG_OWNER"
  CostCenter  = "TBD_TAG_COSTCENTER"
  Env         = "TBD_TAG_ENV"
}
# Networking
corporate_egress_cidrs = ["TBD_CIDR_1/XX","TBD_CIDR_2/XX"]
break_glass_ip         = "TBD_BREAK_GLASS_IP/32"
# VPCs
prod_vpc_id            = "TBD_PROD_VPC_ID"
nonprod_vpc_id         = "TBD_NONPROD_VPC_ID"
# Security groups (optional: if reusing, set to existing IDs and skip creation)
endpoint_allowed_sg_source_cidrs = ["TBD_CIDR_1/XX"]
# Snowflake
snowflake_account_locator = "TBD_SNOWFLAKE_ACCOUNT_LOCATOR"
snowflake_region          = "TBD_SNOWFLAKE_REGION" # e.g., AWS_US_WEST_2
snowflake_org_name        = "TBD_SNOWFLAKE_ORG"    # optional
# Snowflake PrivateLink service names (Snowflake will provide)
snowflake_pl_svc_name     = "TBD_SNOWFLAKE_PL_SERVICE_NAME"
snowflake_ocsp_svc_name   = "TBD_SNOWFLAKE_OCSP_SERVICE_NAME" # optional if using OCSP via PL
# Optional Okta
okta_tenant_url           = "TBD_OKTA_TENANT_URL"  # https://yourorg.okta.com
okta_app_name             = "TBD_OKTA_APP_NAME"
# Optional SIEM
siem_bucket_name          = "TBD_SIEM_BUCKET_NAME"
object_lock_min_days      = "TBD_OBJECT_LOCK_MIN_DAYS"
# Break-glass escalation
break_glass_contact       = "TBD_EMAIL_OR_PHONE"
# Change window
change_window_1           = "TBD_CHANGE_WINDOW_UTC"

terraform/provider.tf
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
provider "aws" {
  region = var.aws_region
}

terraform/variables.tf
variable "aws_account_id" { type = string }
variable "aws_region"     { type = string  default = "us-west-2" }
variable "tags"           { type = map(string) }
variable "corporate_egress_cidrs" { type = list(string) }
variable "break_glass_ip"         { type = string }
variable "prod_vpc_id"            { type = string }
variable "nonprod_vpc_id"         { type = string }
variable "endpoint_allowed_sg_source_cidrs" { type = list(string) }
variable "snowflake_account_locator" { type = string }
variable "snowflake_region"          { type = string }
variable "snowflake_org_name"        { type = string  default = "" }
variable "snowflake_pl_svc_name"     { type = string }
variable "snowflake_ocsp_svc_name"   { type = string  default = "" }
variable "okta_tenant_url"           { type = string  default = "" }
variable "okta_app_name"             { type = string  default = "" }
variable "siem_bucket_name"          { type = string  default = "" }
variable "object_lock_min_days"      { type = string  default = "" }
variable "break_glass_contact"       { type = string  default = "" }

terraform/tags.tf
locals { tags = var.tags }

terraform/kms.tf
resource "aws_kms_key" "snowflake_cmk" {
  description             = "Snowflake CMK for external encryption and integrations"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "EnableRootPermissions"
        Effect   = "Allow"
        Principal = { AWS = "arn:aws:iam::${var.aws_account_id}:root" }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = merge(local.tags, { Name = "snowflake-cmk" })
}
resource "aws_kms_alias" "snowflake_cmk_alias" {
  name          = "alias/snowflake/cmk"
  target_key_id = aws_kms_key.snowflake_cmk.key_id
}

terraform/security_groups.tf
resource "aws_security_group" "pl_endpoint_sg" {
  name        = "snowflake-pl-endpoint-sg"
  description = "Allow HTTPS to Snowflake PrivateLink endpoints"
  vpc_id      = var.prod_vpc_id
  ingress {
    description = "HTTPS from corporate egress and break-glass"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = concat(var.endpoint_allowed_sg_source_cidrs, [var.break_glass_ip])
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = merge(local.tags, { Name = "snowflake-pl-endpoint-sg" })
}
# Optional: duplicate for nonprod if using a separate SG/VPC
resource "aws_security_group" "pl_endpoint_sg_nonprod" {
  name        = "snowflake-pl-endpoint-sg-nonprod"
  description = "Allow HTTPS to Snowflake PrivateLink endpoints (nonprod)"
  vpc_id      = var.nonprod_vpc_id
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = concat(var.endpoint_allowed_sg_source_cidrs, [var.break_glass_ip])
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = merge(local.tags, { Name = "snowflake-pl-endpoint-sg-nonprod" })
}

terraform/privatelink.tf
# These Interface Endpoints require Snowflake-provided service names per account/region.
# Obtain values for var.snowflake_pl_svc_name and var.snowflake_ocsp_svc_name from Snowflake.
resource "aws_vpc_endpoint" "snowflake_pl_prod" {
  vpc_id            = var.prod_vpc_id
  vpc_endpoint_type = "Interface"
  service_name      = var.snowflake_pl_svc_name
  security_group_ids = [aws_security_group.pl_endpoint_sg.id]
  private_dns_enabled = false
  subnet_ids        = toset(data.aws_subnets.prod.ids)
  tags = merge(local.tags, { Name = "snowflake-pl-endpoint-prod" })
}
resource "aws_vpc_endpoint" "snowflake_pl_nonprod" {
  vpc_id            = var.nonprod_vpc_id
  vpc_endpoint_type = "Interface"
  service_name      = var.snowflake_pl_svc_name
  security_group_ids = [aws_security_group.pl_endpoint_sg_nonprod.id]
  private_dns_enabled = false
  subnet_ids        = toset(data.aws_subnets.nonprod.ids)
  tags = merge(local.tags, { Name = "snowflake-pl-endpoint-nonprod" })
}
# Optional OCSP via PrivateLink
resource "aws_vpc_endpoint" "snowflake_ocsp_prod" {
  count             = length(var.snowflake_ocsp_svc_name) > 0 ? 1 : 0
  vpc_id            = var.prod_vpc_id
  vpc_endpoint_type = "Interface"
  service_name      = var.snowflake_ocsp_svc_name
  security_group_ids = [aws_security_group.pl_endpoint_sg.id]
  private_dns_enabled = false
  subnet_ids        = toset(data.aws_subnets.prod.ids)
  tags = merge(local.tags, { Name = "snowflake-ocsp-endpoint-prod" })
}
# Data sources for subnets to place endpoints; adjust filters as needed.
data "aws_subnets" "prod" {
  filter {
    name   = "vpc-id"
    values = [var.prod_vpc_id]
  }
}
data "aws_subnets" "nonprod" {
  filter {
    name   = "vpc-id"
    values = [var.nonprod_vpc_id]
  }
}

terraform/outputs.tf
output "kms_key_arn" { value = aws_kms_key.snowflake_cmk.arn }
output "pl_endpoint_ids" {
  value = {
    prod    = aws_vpc_endpoint.snowflake_pl_prod.id
    nonprod = aws_vpc_endpoint.snowflake_pl_nonprod.id
  }
}

snowflake/network_policy.sql
-- Create or update a network policy restricting access to corporate egress and break-glass.
use role ACCOUNTADMIN;
create network policy if not exists CORP_POLICY
  allowed_ip_list = ('TBD_CIDR_1/XX','TBD_CIDR_2/XX','TBD_BREAK_GLASS_IP/32')
  blocked_ip_list = ();
alter account set network_policy = CORP_POLICY;

snowflake/privatelink_integration.sql
-- Replace placeholders with actual values from Terraform outputs and Snowflake.
use role ACCOUNTADMIN;
-- Register AWS VPC endpoints that will connect to Snowflake
create or replace security integration AWS_PRIVATELINK_INTEGRATION
  type = privatelink
  enabled = true
  cloud = aws
  allowed_vpce_ids = ('TBD_VPCE_ID_PROD','TBD_VPCE_ID_NONPROD')
  comment = 'PrivateLink integration for account TBD_SNOWFLAKE_ACCOUNT_LOCATOR in region TBD_SNOWFLAKE_REGION';
-- Optional: OCSP via PrivateLink
alter account set use_ocsp_fail_open = false;

snowflake/optional_oauth_okta.sql
-- Populate only if using Okta; otherwise skip.
use role ACCOUNTADMIN;
create or replace security integration OKTA_OAUTH
  type = oauth
  oauth_client = 'EXTERNAL_OAUTH'
  enabled = true
  oauth_issuer = 'TBD_OKTA_TENANT_URL/oauth2/default'
  oauth_client_type = 'CONFIDENTIAL'
  oauth_redirect_uri = 'https://TBD_OKTA_APP_CALLBACK'
  oauth_allow_non_tls_redirect_uri = false
  oauth_enforce_pkce = true
  oauth_allowed_scopes = ('SESSION:ROLE-ANY')
  comment = 'Okta OAuth for Snowflake - app TBD_OKTA_APP_NAME';

iam/snowflake_external_role.tf
# Optional: for future S3 stages or SIEM delivery. Attach bucket policy in siem_bucket_policy.json if using.
resource "aws_iam_role" "snowflake_external" {
  name               = "snowflake-external-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = { AWS = "TBD_SNOWFLAKE_AWS_EXTERNAL_ID_OR_ACCOUNT" },
      Action = "sts:AssumeRole",
      Condition = {
        StringEquals = {
          "sts:ExternalId" = "TBD_EXTERNAL_ID"
        }
      }
    }]
  })
  tags = merge({ Name = "snowflake-external-role" }, var.tags)
}
# Example policy for SIEM bucket access (optional)
resource "aws_iam_policy" "siem_access" {
  name   = "siem-bucket-access"
  policy = file("${path.module}/siem_bucket_policy.json")
}
resource "aws_iam_role_policy_attachment" "attach_siem_access" {
  count      = length(var.siem_bucket_name) > 0 ? 1 : 0
  role       = aws_iam_role.snowflake_external.name
  policy_arn = aws_iam_policy.siem_access.arn
}

iam/siem_bucket_policy.json
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ReadWriteSIEMBucket",
      "Effect": "Allow",
      "Action": [
        "s3:PutObject",
        "s3:GetObject",
        "s3:ListBucket"
      ],
      "Resource": [
        "arn:aws:s3:::TBD_SIEM_BUCKET_NAME",
        "arn:aws:s3:::TBD_SIEM_BUCKET_NAME/*"
      ]
    },
    {
      "Sid": "EnforceObjectLockIfEnabled",
      "Effect": "Allow",
      "Action": [
        "s3:PutObjectRetention",
        "s3:GetObjectRetention"
      ],
      "Resource": "arn:aws:s3:::TBD_SIEM_BUCKET_NAME/*",
      "Condition": {
        "NumericGreaterThanEquals": {
          "s3:object-lock-remaining-retention-days": TBD_OBJECT_LOCK_MIN_DAYS
        }
      }
    }
  ]
}

runbooks/01-prep-and-prereqs.md
- Confirm or override region (default us-west-2).
- Obtain Snowflake PrivateLink service names and OCSP service (if used): TBD_SNOWFLAKE_PL_SERVICE_NAME, TBD_SNOWFLAKE_OCSP_SERVICE_NAME.
- Collect VPC IDs for prod/nonprod, target subnets for interface endpoints, and corporate egress CIDRs and break-glass IP.
- Ensure ACCOUNTADMIN in Snowflake and AWS permissions to create KMS, VPC endpoints, and IAM.
- Populate vars.auto.tfvars and apply Terraform: terraform init && terraform apply.
- Capture outputs: kms_key_arn, pl_endpoint_ids.
- Insert endpoint IDs into snowflake/privatelink_integration.sql and run in Snowflake.

runbooks/02-change-window-1.md
- Scope: Enable network policy, validate PrivateLink reachability, and basic auth.
- Steps:
  1) Create/alter CORP_POLICY and set on account.
  2) Create AWS_PRIVATELINK_INTEGRATION with VPCE IDs from Terraform.
  3) Test connectivity from prod/nonprod VPCs to Snowflake via endpoint.
  4) Optionally configure OCSP via PrivateLink.
  5) Rollback plan: unset network policy; disable integration; delete endpoints if required.

runbooks/03-validation-checklist.md
- Snowflake login allowed from corporate CIDRs and break-glass IP; denied elsewhere.
- NSLookup for Snowflake account URL resolves per PrivateLink guidance.
- TCP 443 connectivity succeeds from prod/nonprod subnets to PrivateLink endpoints.
- KMS CMK exists with rotation enabled and alias/snowflake/cmk attached.
- Optional: Okta OAuth flow returns tokens; roles mapped as expected.
- Optional: SIEM bucket policy attached to role and object lock minimum retention enforced.

Notes on TBDs and where they appear
- Snowflake
  - Account locator: TBD_SNOWFLAKE_ACCOUNT_LOCATOR
  - Region: TBD_SNOWFLAKE_REGION
  - Org name: TBD_SNOWFLAKE_ORG
  - PrivateLink service names: TBD_SNOWFLAKE_PL_SERVICE_NAME, TBD_SNOWFLAKE_OCSP_SERVICE_NAME
- AWS
  - Account ID: TBD_AWS_ACCOUNT_ID
  - Prod/Nonprod VPC IDs: TBD_PROD_VPC_ID, TBD_NONPROD_VPC_ID
  - Corporate egress CIDRs: TBD_CIDR_1/XX, TBD_CIDR_2/XX
  - Break-glass IP: TBD_BREAK_GLASS_IP/32
  - SIEM bucket: TBD_SIEM_BUCKET_NAME, Object Lock: TBD_OBJECT_LOCK_MIN_DAYS
- Identity
  - Okta tenant URL: TBD_OKTA_TENANT_URL
  - Okta app name: TBD_OKTA_APP_NAME
  - Break-glass contact: TBD_EMAIL_OR_PHONE
- Change window
  - Dates/times: TBD_CHANGE_WINDOW_UTC

If you want me to tailor this fully, provide the TBD values and I’ll fill them in and validate each artifact.

